process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
const WP='https://dev.avesa.lt';
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim().replace(/\s+/g,'')).toString('base64');
const K='';
const TOK='ps'+Date.now();
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg, content:buf.toString('base64')};
  if(sha) body.sha=sha;
  const r2=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  return r2.status;
}
const out={zingsniai:[],klaidos:[],konsole:[]};
let snipId=0;
try{
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active && /^TEMP/i.test(s.name||''))){
    await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${t.id}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
  }
  const code = "add_action('init',function(){ if(!isset($_GET['ps_dep31'])){ if(!isset($_GET['ps_al'])||$_GET['ps_al']!=='"+TOK+"'){return;} $u=get_users(['role'=>'administrator','number'=>1]); wp_set_current_user($u[0]->ID); wp_set_auth_cookie($u[0]->ID,false); wp_safe_redirect(admin_url('admin.php?page=ps-katalogas')); exit; } if($_GET['ps_dep31']!=='"+TOK+"'){return;} $k=WPMU_PLUGIN_DIR.'/petshop-katalogas.php'; $sen=file_get_contents($k); update_option('ps_katalogas_v30_bak',base64_encode($sen),false); $c=base64_decode('"+K+"'); file_put_contents($k,$c); wp_send_json(['dydis'=>filesize($k),'md5'=>md5_file($k)===md5($c),'atsargine'=>strlen($sen)]); });";
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name:'TEMP v31', code, scope:'global', active:true})});
  const s=await r.json(); snipId=s.id||0;
  out.zingsniai.push('snippetas #'+snipId);
  await new Promise(x=>setTimeout(x,2500));
  const dep=await fetch(`${WP}/?ps_dep31=${TOK}`,{headers:{Authorization:AUTH}});
  out.diegimas=await dep.text();
  out.zingsniai.push('katalogas idiegtas');
}catch(e){ out.klaidos.push('deploy: '+String(e).slice(0,200)); }
if(!snipId){ await put('analize/v31.json',Buffer.from(JSON.stringify(out,null,2)),'v31'); process.exit(0); }
await new Promise(x=>setTimeout(x,3000));

const b=await chromium.launch({args:['--ignore-certificate-errors']});
const ctx=await b.newContext({viewport:{width:1620,height:1150}, ignoreHTTPSErrors:true});
const pg=await ctx.newPage();
pg.on('console', m=>{ if(m.type()==='error') out.konsole.push(m.text().slice(0,140)); });
pg.on('pageerror', e=>out.klaidos.push('JS: '+String(e).slice(0,140)));
try{
  await pg.goto(`${WP}/?ps_al=${TOK}`,{waitUntil:'networkidle',timeout:90000});
  await pg.waitForTimeout(3000);
  out.stulpeliai=await pg.$$eval('.pskat-t thead th', t=>t.map(x=>x.innerText.trim().replace(/\n/g,' ')));
  out.stulpeliu_n=out.stulpeliai.length;
  // ar lentelė telpa
  out.plotis=await pg.evaluate(()=>{ const t=document.querySelector('.pskat-t'); if(!t) return null;
    return {lenteles:t.scrollWidth, konteinerio:t.parentElement.clientWidth, telpa:t.scrollWidth<=t.parentElement.clientWidth+2}; });
  out.langeliai={pard:await pg.$$eval('.pard-gr',e=>e.length), bukle:await pg.$$eval('.bukle',e=>e.length), piln:await pg.$$eval('.piln',e=>e.length)};
  await put('screenshots/v31_sarasas.png', await pg.screenshot(), 'v31 sarasas');
  out.zingsniai.push('sarasas OK');
  await pg.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&q=Animonda`,{waitUntil:'networkidle',timeout:90000});
  await pg.waitForTimeout(2500);
  await pg.evaluate(()=>{ const a=document.querySelector('a.atv'); if(a) a.click(); });
  await pg.waitForTimeout(4000);
  out.kortele=await pg.$$eval('.kort-antr', e=>e.map(x=>x.innerText.trim().replace(/\n/g,' ').slice(0,40)));
  out.pilnumo_blokai=out.kortele.filter(x=>x.toUpperCase().includes('PILNUM')).length;
  await put('screenshots/v31_kortele.png', await pg.screenshot(), 'v31 kortele');
  out.zingsniai.push('kortele OK');
}catch(e){ out.klaidos.push('EIGA: '+String(e).slice(0,250)); }
await b.close();
try{ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${snipId}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); out.zingsniai.push('snippetas deaktyvuotas'); }catch(e){}
await put('analize/v31.json',Buffer.from(JSON.stringify(out,null,2)),'v31');
console.log('baigta');
